<script setup lang="ts">definePageMeta({layout:'admin'});const route=useRoute();const {data,pending,error}=await useFetch(`/api/admin/products/${route.params.id}`,{transform:(r:any)=>r.data});const message=ref('');function saved(){message.value='Produk berhasil disimpan.'}</script><template><div class="admin-page"><AdminPageHeader title="Edit produk" description="Perbarui informasi, foto, harga, dan stok."/><p v-if="message" class="success">{{message}}</p><div v-if="pending">Memuat produk…</div><p v-else-if="error" class="error">Produk tidak dapat dimuat.</p><ProductForm v-else :product="data" @saved="saved"/></div></template><style scoped>.success{color:var(--success)}</style>
